    reply.header("Cache-Control", "private, no-store");
    if (!platformPixelInBrowser(ctx) || req.auth) return { pixel: null, signedIn: !!req.auth };
    const api = ctx.config.PUBLIC_API_URL.replace(/\/$/, "");
