  const defaultCurrency = defaultPixel?.currency ?? String(orgCur.rows[0]?.reporting_currency ?? "BRL").trim();
  const normalized2 = adapter.normalize(payload, { defaultCurrency, amountUnit: integration.amount_unit, now: ctx.now });
