        ctx,
        integration.org_id,
        { ...sale, body: `${p.amount} \u2022 ${p.pixelName ?? ADAPTERS[input2.provider].label}` },
        { ...sale, body: `${p.amount} \u2022 ${ADAPTERS[input2.provider].label}` }
